tool_calls:
diff <(sort /data/installed.txt) <(sort /data/required.txt) | awk '
/^> / { install[++ni] = substr($0, 3) }
/^< / { remove[++nr] = substr($0, 3) }
END {
  print "To install:"
  for (i = 1; i <= ni; i++) print install[i]
  print "To remove:"
  for (i = 1; i <= nr; i++) print remove[i]
}'

